insert into public.units (id, title) values (1, '單元一')
insert into public.questions (unit_id, qtype, stem, options, answers, explanation, fingerprint) values
  (1, 'single', '企業組織在追求利潤與價值創造的過程中，下列哪一項是屬於效能(effectiveness)而非效率(efficiency)的問題？', array['所追求目標的人員數量是否最少', '所追求目標的成本是否最低', '所追求目標的本身是否恰當', '所追求目標的資金是否最少']::text[], array['所追求目標的本身是否恰當']::text[], null, 'd9464de8d650ede116c2442404d29687c1b413567812f18ac184cba973274cbf'),
  (1, 'single', '下列敍述何者有誤？', array['管理是協調工作項目，使工作能藉由他人之力，有效率及有效能的完成', '控制是監督各項活動，確保所有工作按計畫執行', '規劃是訂定目標，建立達成目標的策略及發展一套有系統的計畫，來整合協調企業各項活動', '管理功能分為行銷、生產、財務、研究發展及人力資源']::text[], array['管理功能分為行銷、生產、財務、研究發展及人力資源']::text[], null, '913a07003b759243196815a1d1a068075830fbc6b80887d7be8abaa80b52e1d8'),
  (1, 'single', '管理者架構達到組織目標的過程被叫︰', array['證明', '控制', '規劃', '領導', '組織']::text[], array['規劃']::text[], null, 'f4070b29b3fe1492c5abb38e1bbee599094741bf2a2420260c1e87c69c828347'),
  (1, 'single', '當一位管理者傳遞下屬一份公司政策的文件時，他正扮演什麼角色？', array['資源分配者', '監視者', '頭臉人物', '問題解決者', '傳播者']::text[], array['傳播者']::text[], null, '44f9a49a84a1676a8bf72566bbf9570b4e46a10280f7fbf8163f63f6bf3c579e'),
  (1, 'single', '當豐田汽車的總裁豐田章男在電視上說明豐田汽車的召回行動時，他正扮演著何種角色？', array['領導人', '發言人', '協調人', '聯絡人']::text[], array['發言人']::text[], null, '45bb7be44cb8af3c2f0a0c330bcf5febb61c5ae80907da3676ddf94fceb7303f'),
  (1, 'single', '管理者有不同角色，下列何者為決策角色？', array['監督者', '資源分配者', '聯絡人', '發言人']::text[], array['資源分配者']::text[], null, 'c01959f29676f9e31f97fd35cc9aec7db31ff596dd046650f2634c24e0fdeb6a'),
  (1, 'single', '管理者為確保能達成目標，針對組織目標、偵測、比較、評估及改正的程序，係屬下列何項管理功能？', array['控制', '領導', '組織', '規劃']::text[], array['控制']::text[], null, '3c95fe7498f2f0c73fba6ba1a9b5e0bdef61a18a45d38fc295a7e69fe138bce7'),
  (1, 'single', '釐清因果問題並且分析診斷問題的能力被叫︰', array['概念技能', '技術技能', '以上皆非', '談判技能', '為人處事技能']::text[], array['概念技能']::text[], null, '37104465fc251b2162e7025b863484da35fc8e4ac2ea234b0302bf578e8db560'),
  (1, 'single', '效率與效果之間的關係為？', array['二者相互獨立沒有關係', '效率就是效果', '有效率才會有效果', '有效果才會有效率', '以上皆是']::text[], array['二者相互獨立沒有關係']::text[], null, '822d7865d5f46de410731679e09d711e919b4f84242b23b53796a699d1b4e34f'),
  (1, 'single', '當企業組織偏離目標可接受範圍時，可以透過下列何機制提供組織適當的矯正行動，並進一步的調整目標？', array['規劃', '組織', '領導', '控制']::text[], array['控制']::text[], null, 'a0802d62bc17ddde1b3e803e8f7b012064aa09714da713c3ec622f12d78398f3'),
  (1, 'single', '高階管理人員所應具備的三種管理能力中，由高而低之排序為：', array['人際關係能力、概念能力、技術能力', '概念能力、技術能力、人際關係能力', '人際關係能力、技術能力、概念能力', '概念能力、人際關係能力、技術能力']::text[], array['概念能力、人際關係能力、技術能力']::text[], null, '2ea5f67762428857e2ca9f1b9f3a040c975c6fb301fb804cea7cfa9855b4ba9c'),
  (1, 'single', '羅伯‧凱茲(Robert Katz)指出管理者應具備的三種能力為：', array['技術能力、人際關係能力、概念化能力', '技術能力、人際關係能力、政治能力', '技術能力、概念化能力、政治能力', '人際關係能力、概念化能力、政治能力']::text[], array['技術能力、人際關係能力、概念化能力']::text[], null, '2eb4183773eac9183afccc696bea6de18c09b58f4eec23c4328ce72dd27455c2'),
  (1, 'single', '在公司的新工廠的開幕式剪綵的一位管理者，正扮演組織哪個角色？', array['頭臉人物', '資源分配者', '談判者', '監視者', '聯絡人']::text[], array['頭臉人物']::text[], null, 'be712edb5222f8ca0160473cb5708995ce5dc13b9f01ff1bd5573adbefaaef3e'),
  (1, 'single', '當麥當勞發展薯條油炸機器時，油的使用數量降低30%，這是一個改進組織的______的例子︰', array['效果', '效率', '規劃', '低成本策略', '組織']::text[], array['效率']::text[], null, 'c45dd07888eaf4fa64db66584cc4cff451f9a7dc4b33929c2787b3176b3e839d'),
  (1, 'single', '在形成計劃之後，為了確保計劃的進行，管理者必須監控與評估組織績效，並將實際與預期之績效落差做比較，並予以修正，稱為下列何者？', array['組織', '規劃', '領導', '控制']::text[], array['控制']::text[], null, 'c83e05d108620205fc56db3e60c70b34779bc6162c34ca8418e26beac6db8a69'),
  (1, 'single', '以下哪個不是管理者在變動環境下面對的管理議題：', array['如何監控每一個員工的工作', '後現代管理的典範發展', '多元文化的尊重與認同', '創新與創業精神的開展']::text[], array['如何監控每一個員工的工作']::text[], null, '5927652c0149ed8f65b7b87c6e72a94862d49331235b4127ad70252dd80a97f7'),
  (1, 'single', '下列有關「管理者」的敍述，何者為非：', array['建築工人領班不算是管理者', '可能需要直接對一群人負責，也可能是單一地監督下屬', '可能需與其他部門或其他組織的成員聯繫', '監督他人執行活動的人']::text[], array['建築工人領班不算是管理者']::text[], null, '472ad632f287ec37ccb87579fc52ab85f9ff996827f5ed4f2e8d5ba04eeedec4'),
  (1, 'single', 'Katz認為中階層管理者必須具備的技能，下列何者為是？', array['技術性能力', '以上皆是', '觀念化能力', '人際關係能力']::text[], array['以上皆是']::text[], null, '2712060d751ef2adb484764098fc40086305a9de35ee8ceadb36241d26184942'),
  (1, 'single', '閔茲柏格(Henry Mintzberg)所提出的管理的十大角色中聯絡者(liaison)是屬於下列何種類型角色？', array['決策角色', '傳播角色', '人際關係角色', '資訊角色']::text[], array['人際關係角色']::text[], null, '273f54be57c77a9620bc9f149d4393b5731ebacd6bfd2a81c871949a775255cb'),
  (1, 'single', '企業經營會面臨效率(efficiency)與效能(effectiveness)的問題。下列有關效率與效能的敍述，何者正確：', array['效率是目標問題', '效能是指投入與產出的關係', '效能是指成本問題', '效率是指投入與產出的關係']::text[], array['效率是指投入與產出的關係']::text[], null, '04dec98d284dee905dc4c2f984376f397dd369c1f533602396dc94bfece1735b')
